const req = $('When Executed by Another Workflow').first().json;
const draft = $('Get Draft').first().json;
const current = $input.first().json;
const fallbackImage = 'https://raw.githubusercontent.com/tha0rbej/hanoixanh/main/anh-chien-dich-kenh-muong.png';
if (!draft.id) throw new Error('draft_not_found');
if (!current.id) throw new Error('version_not_found: version mới nhất không tồn tại');
if (Number(req.base_version) !== Number(draft.current_version)) throw new Error('stale_version: version mới nhất là ' + draft.current_version);
if (['approved', 'publishing', 'published', 'partial_failure'].includes(draft.status)) throw new Error('approved_version_is_immutable');
if (!String(req.feedback || '').trim()) throw new Error('missing_information: feedback');
const parse = (v, f, fb) => { if (v === undefined || v === null || v === '') return fb; if (typeof v !== 'string') return v; try { return JSON.parse(v); } catch (e) { if (f === 'sources' || f === 'images') return fb; throw new Error('invalid_json: ' + f); } };
const mergePayload = (base, incoming) => { const out = { ...(base && typeof base === 'object' ? base : {}) }; for (const [key, value] of Object.entries(incoming && typeof incoming === 'object' ? incoming : {})) if (value !== undefined && value !== null && value !== '') out[key] = value; return out; };
const safeImage = value => { const v = String(value ?? '').trim(); return /^https:\/\/\S+$/i.test(v) ? v : null; };
const existingWebsite = parse(current.website_payload, 'current_website_payload', {});
const existingThreads = parse(current.threads_payload, 'current_threads_payload', {});
const website = mergePayload(existingWebsite, parse(req.website_payload, 'website_payload', {}));
const threads = mergePayload(existingThreads, parse(req.threads_payload, 'threads_payload', {}));
if (!website || typeof website !== 'object' || !String(website.title || '').trim()) throw new Error('invalid_payload: website_payload cần có title');
if (!String(website.pollution_status || '').trim()) throw new Error('missing_information: website_payload.pollution_status');
if (!String(website.objective || '').trim()) throw new Error('missing_information: website_payload.objective');
if (!String(website.support_equipment || '').trim()) throw new Error('missing_information: website_payload.support_equipment');
if (!threads || typeof threads !== 'object' || !String(threads.text || threads.content || '').trim()) throw new Error('invalid_payload: threads_payload cần có text');
if (String(threads.text || threads.content).length > 500) throw new Error('threads_text_too_long: tối đa 500 ký tự');
const imagesRaw = parse(req.images, 'images', parse(current.images, 'current_images', []));
const sourcesRaw = parse(req.sources, 'sources', parse(current.sources, 'current_sources', []));
const images = Array.isArray(imagesRaw) ? imagesRaw : [];
const sources = Array.isArray(sourcesRaw) ? sourcesRaw : [];
const validImages = images.filter(image => safeImage(typeof image === 'string' ? image : image?.url));
const imageUrl = validImages.map(image => safeImage(typeof image === 'string' ? image : image?.url)).find(Boolean) || fallbackImage;
const storedImages = validImages.length ? validImages : [{ url: fallbackImage, caption: 'Ảnh chiến dịch Hà Nội Xanh', source_url: fallbackImage, license_status: 'project_asset' }];
website.image_url = safeImage(website.image_url) || imageUrl;
threads.image_url = safeImage(threads.image_url) || imageUrl;
return [{ json: { ...req, next_version: Number(draft.current_version) + 1, website_payload: website, threads_payload: threads, images: storedImages, sources } }];

const draft = $input.first().json;
const v = $('Create Revised Version').first().json;
return [{ json: { status: 'in_review', draft: { ...draft, draft_id: draft.id, version: v.version, website_payload: v.website_payload, threads_payload: v.threads_payload, images: v.images, sources: v.sources } } }];
